<?php require 'config/database.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM rifas WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('Rifa não encontrada');$used=$pdo->prepare("SELECT numero FROM bilhetes WHERE rifa_id=? AND status IN ('reservado','pago')");$used->execute([$id]);$used=array_flip(array_column($used->fetchAll(),'numero'));?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($r['titulo'])?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="top"><div class="wrap"><a href="index.php">← Voltar</a></div></header><main class="wrap"><div class="box"><h1><?=e($r['titulo'])?></h1><p><?=nl2br(e($r['descricao']))?></p><div class="price">R$ <?=number_format($r['preco'],2,',','.')?> / bilhete</div></div><form class="box" method="post" action="checkout.php"><input type="hidden" name="rifa_id" value="<?=$id?>"><?php if($r['tipo']==='selecionavel'):?><h3>Escolha seus números</h3><div class="numbers"><?php for($i=0;$i<$r['total_numeros'];$i++):$off=isset($used[$i]);?><label class="num <?=$off?'off':''?>"><input style="display:none" type="checkbox" name="numeros[]" value="<?=$i?>" <?=$off?'disabled':''?>><?=str_pad($i,strlen((string)($r['total_numeros']-1)),'0',STR_PAD_LEFT)?></label><?php endfor;?></div><?php else:?><h3>Quantos bilhetes?</h3><input type="number" name="quantidade" min="1" max="100" value="1" required><?php endif;?><h3>Seus dados</h3><input name="nome" placeholder="Nome completo" required><input name="telefone" placeholder="WhatsApp"><input type="email" name="email" placeholder="E-mail"><button class="btn" type="submit">Continuar</button></form></main><script>document.querySelectorAll('.num:not(.off)').forEach(x=>x.onclick=()=>setTimeout(()=>x.classList.toggle('sel',x.querySelector('input').checked),0));</script></body></html>
